import {
  CalculatorCatalogResponse,
  CalculatorRunResponse,
  CalculatorRunServiceRequest,
  CalculatorSchemaResponse,
  GetCalculatorRequest,
  MetadataQuery,
} from "@taxkit/calculators/schemas";
import { PublicCalculatorService } from "@taxkit/calculators/service";
import {
  DocsPublicNavigation,
  DocsPublicPage,
  DocsPublicPagePath,
  DocsSearchTerm,
} from "@taxkit/content/schemas";
import { ContentService } from "@taxkit/content/service";
import { Effect, Layer, Match, Schema } from "effect";
import { McpProtocol, McpServer, Tool, Toolkit } from "effect/ai";

import { withMcpRequestCancellation } from "./mcp-cancellation.boundary.js";
import { McpDocsSearchResponse, McpToolUnavailable } from "./mcp.schemas.js";
import type { ApiWorkerSettings } from "./schemas.js";

const TaxKitMcpToolkit = Toolkit.make(
  Tool.make("taxkit_list_calculators", {
    description:
      "List the supported calculators and their current input and output facts.",
    failure: McpToolUnavailable,
    parameters: MetadataQuery,
    success: CalculatorCatalogResponse,
  })
    .annotate(Tool.Readonly, true)
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true),
  Tool.make("taxkit_get_calculator_schema", {
    description:
      "Read a supported calculator's input questions, output facts, rules and sources before calculating.",
    failure: McpToolUnavailable,
    parameters: GetCalculatorRequest,
    success: CalculatorSchemaResponse,
  })
    .annotate(Tool.Readonly, true)
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true),
  Tool.make("taxkit_calculate", {
    description:
      "Run a supported calculator with checked facts and return its report. Uses the shared anonymous calculation allowance. Figures are not saved. Do not retry automatically.",
    failure: McpToolUnavailable,
    parameters: CalculatorRunServiceRequest,
    success: CalculatorRunResponse,
  })
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true),
  Tool.make("taxkit_docs_navigation", {
    description:
      "Find the accepted public documentation pages through the same navigation as the website.",
    failure: McpToolUnavailable,
    parameters: Tool.EmptyParams,
    success: DocsPublicNavigation,
  })
    .annotate(Tool.Readonly, true)
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true),
  Tool.make("taxkit_find_docs", {
    description:
      "Search accepted public documentation using up to 100 characters of search words.",
    failure: McpToolUnavailable,
    parameters: Schema.Struct({ term: DocsSearchTerm }),
    success: McpDocsSearchResponse,
  })
    .annotate(Tool.Readonly, true)
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true),
  Tool.make("taxkit_read_doc", {
    description:
      "Read an accepted public documentation page, including its processed Markdown, at a discovered page address.",
    failure: McpToolUnavailable,
    parameters: Schema.Struct({ path: DocsPublicPagePath }),
    success: DocsPublicPage,
  })
    .annotate(Tool.Readonly, true)
    .annotate(Tool.Destructive, false)
    .annotate(Tool.OpenWorld, false)
    .annotate(Tool.Strict, true)
);

const TaxKitMcpHandlersLive = TaxKitMcpToolkit.toLayer(
  Effect.gen(function* () {
    const calculator = yield* PublicCalculatorService;
    const content = yield* ContentService;
    return TaxKitMcpToolkit.of({
      taxkit_calculate: Effect.fn("TaxKitMcp.calculate")((request) =>
        calculator.calculate(request).pipe(
          Effect.mapError((error) =>
            Match.value(error).pipe(
              Match.tag(
                "CalculatorRateLimited",
                () =>
                  new McpToolUnavailable({
                    code: "rate-limited",
                    retry: "wait-then-try-manually",
                  })
              ),
              Match.tag(
                "CalculatorCapacityExceeded",
                () =>
                  new McpToolUnavailable({
                    code: "capacity-exceeded",
                    retry: "try-again-manually",
                  })
              ),
              Match.tag(
                "CalculatorOperationTimedOut",
                () =>
                  new McpToolUnavailable({
                    code: "operation-timeout",
                    retry: "try-again-manually",
                  })
              ),
              Match.tag(
                "CalculatorAdmissionUnavailable",
                () =>
                  new McpToolUnavailable({
                    code: "service-unavailable",
                    retry: "try-again-manually",
                  })
              ),
              Match.tag(
                "CalculationError",
                "CalculatorInputDecodeError",
                "UnsupportedCalculatorError",
                "UnsupportedCalculatorContextError",
                () =>
                  new McpToolUnavailable({
                    code: "invalid-calculation",
                    retry: "check-input-before-retrying",
                  })
              ),
              Match.exhaustive
            )
          ),
          withMcpRequestCancellation
        )
      ),
      taxkit_docs_navigation: Effect.fn("TaxKitMcp.docsNavigation")(() =>
        content.getNavigation().pipe(withMcpRequestCancellation)
      ),
      taxkit_find_docs: Effect.fn("TaxKitMcp.findDocs")(({ term }) =>
        content.searchPages(term).pipe(
          Effect.map((results) => ({ results })),
          Effect.mapError(
            () =>
              new McpToolUnavailable({
                code: "service-unavailable",
                retry: "try-again-manually",
              })
          ),
          withMcpRequestCancellation
        )
      ),
      taxkit_get_calculator_schema: Effect.fn("TaxKitMcp.getCalculatorSchema")(
        (request) =>
          calculator.getCalculatorSchema(request).pipe(
            Effect.mapError(
              () =>
                new McpToolUnavailable({
                  code: "service-unavailable",
                  retry: "try-again-manually",
                })
            ),
            withMcpRequestCancellation
          )
      ),
      taxkit_list_calculators: Effect.fn("TaxKitMcp.listCalculators")((query) =>
        calculator.listCalculators(query).pipe(
          Effect.mapError(
            () =>
              new McpToolUnavailable({
                code: "operation-timeout",
                retry: "try-again-manually",
              })
          ),
          withMcpRequestCancellation
        )
      ),
      taxkit_read_doc: Effect.fn("TaxKitMcp.readDoc")(({ path }) =>
        content.getPage(path).pipe(
          Effect.mapError(
            () =>
              new McpToolUnavailable({
                code: "service-unavailable",
                retry: "try-again-manually",
              })
          ),
          withMcpRequestCancellation
        )
      ),
    });
  })
);

// The composition root selects the native adapter. Each host keeps its own
// native protocol scope while using the captured calculator/content owners.
// Origin-less desktop and server clients are admitted; browser pages must be
// served from the publication address. Add another site only for a known need.
export const TaxKitMcpHttpLayer = (
  publicationOrigin: ApiWorkerSettings["publicationOrigin"],
  protocol: McpProtocol.ProtocolAdapter = McpProtocol.v2026_07_28
) =>
  McpServer.toolkit(TaxKitMcpToolkit).pipe(
    Layer.provide(TaxKitMcpHandlersLive),
    Layer.provide(
      McpServer.layerHttp({
        allowedOrigins: [publicationOrigin.origin],
        name: "TaxKit",
        path: "/mcp",
        protocols: [protocol],
        version: "1",
      })
    )
  );
import { CollectionPolicyHeader } from "@taxkit/analytics/schemas";
import {
  applyCachePolicy,
  isPublicReadPath,
} from "@taxkit/api-http/response-policy";
import { TaxKitApiRoutesLayer } from "@taxkit/api-http/server";
import { CalculatorRpcResponseTooLarge } from "@taxkit/api-rpc/errors";
import { CalculatorHostMode, calculatorEdgeRateKey } from "./edge-identity.boundary.js";
import { CalculatorClientRateKey } from "@taxkit/calculators/admission.schemas";
import { CalculatorRequestRateKey } from "@taxkit/calculators/admission.service";
import {
  CalculatorRpcDeadline,
  CalculatorRpcResponseLimit,
} from "@taxkit/api-rpc/schemas";
import { TaxKitRpcHttpLayer } from "@taxkit/api-rpc/server";
import { CalculatorId } from "@taxkit/calculators/schemas";
import { PublicCalculatorService } from "@taxkit/calculators/service";
import { DocsSourceError } from "@taxkit/content/errors";
import { ContentDiscoveryLive } from "@taxkit/content/live";
import {
  DocsDiscoveryPath,
  DocsDiscoverySettings,
} from "@taxkit/content/schemas";
import {
  ContentCatalogue,
  ContentDiscovery,
  ContentService,
} from "@taxkit/content/service";
import { safeHttpEffect } from "alchemy/Http";
import {
  Array,
  ByteSize,
  Config,
  Context,
  Effect,
  Layer,
  Option,
  Record,
  Result,
  Schema,
                      "127.0.0.1"
                    ).pipe(Effect.map(Option.some))
                  : Effect.succeed(Option.none())
              )
            )
          : Effect.succeed(Option.none())
      ),
      Effect.catchTags({
        ConfigError: () => Effect.succeedNone,
        SchemaError: () => Effect.succeedNone,
      })
    )
  );
  const telemetry = yield* Layer.build(ApiSafeTelemetryLive);
  const calculator = Layer.succeed(
    PublicCalculatorService,
    yield* PublicCalculatorService
  );
  const content = Layer.succeed(ContentService, yield* ContentService);
  const discovery = ContentDiscoveryLive(
    settings.pipe(
      Effect.map((config) =>
        DocsDiscoverySettings.make({
          apiOrigin: config.apiOrigin,
          publicationOrigin: config.publicationOrigin,
        })
      ),
      Effect.mapError(
        () =>
          new DocsSourceError({
            message: "Documentation discovery settings are unavailable.",
            operation: "getDiscoveryDocument",
          })
      )
    )
  ).pipe(
    Layer.provide(Layer.succeed(ContentCatalogue, yield* ContentCatalogue))
  );
  const routes = Layer.mergeAll(
    TaxKitApiRoutesLayer,
    TaxKitRpcHttpLayer.pipe(Layer.provide(calculator)),
    DiscoveryRoutes.pipe(HttpRouter.provideRequest(discovery))
  ).pipe(
    Layer.provide(Layer.merge(content, discovery)),
    HttpRouter.provideRequest(calculator)
  );
  const handler = yield* HttpRouter.toHttpEffect(routes).pipe(
    Effect.provideContext(telemetry)
  );
  const instanceScope = yield* Scope.Scope;
  const sessions = yield* McpSessionHost;
  // Build the protocol host once on first use, after native addresses resolve.
  // Retain its fibres in the instance Scope, and keep the first caller's
  // request/key out of registration. Each call receives its own native Context.
  const mcp = yield* Effect.cached(
    settings.pipe(
      Effect.flatMap((config) =>
        HttpRouter.toHttpEffect(
          TaxKitMcpHttpLayer(config.publicationOrigin).pipe(
            Layer.provide(calculator),
            Layer.provide(content)
          )
        )
      ),
      Scope.provide(instanceScope),
      Effect.updateContext((context: Context.Context<never>) =>
        Context.omit(
          ApiCalculatorEvents,
          CalculatorRequestRateKey,
          McpRequestAbortSignal,
          HttpServerRequest.HttpServerRequest
        )(context)
      ),
      Effect.provideContext(telemetry),
      Effect.catchTags({
        ConfigError: () =>
          Effect.succeed(
            Effect.succeed(HttpServerResponse.empty({ status: 503 }))
          ),
        IllegalArgumentError: () =>
          Effect.succeed(
            Effect.succeed(HttpServerResponse.empty({ status: 503 }))
          ),
      })
    )
  );
import { CalculatorClientRateKey } from "@taxkit/calculators/admission.schemas";
import { CalculatorRequestRateKey } from "@taxkit/calculators/admission.service";
import { PublicCalculatorService } from "@taxkit/calculators/service";
import { ContentService } from "@taxkit/content/service";
import { DurableObject, DurableObjectState } from "alchemy/Cloudflare/Workers";
import { safeHttpEffect } from "alchemy/Http";
import type { HttpEffect } from "alchemy/Http";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import {
  Context,
  DateTime,
  Effect,
  Exit,
  Layer,
  Option,
  Redacted,
  Ref,
  Schema,
  Scope,
  Semaphore,
  SynchronizedRef,
} from "effect";
import { McpProtocol } from "effect/ai";
import {
  Headers,
  HttpRouter,
  HttpServerRequest,
  HttpServerResponse,
} from "effect/http";
import { NetAddress } from "effect/net";

import {
  ApiCalculatorDelivery,
  withCalculatorAnalytics,
} from "./analytics-request.boundary.js";
import { ApiCalculatorEvents } from "./calculator-analytics.layer.js";
import { McpRequestAbortSignal } from "./mcp-request.service.js";
import { withBoundedMcpReply } from "./mcp-response.boundary.js";
import {
  McpSessionId,
  McpSessionInitialisationLimit,
  McpSessionLifetime,
  McpSessionRequestLimit,
} from "./mcp.schemas.js";
import { TaxKitMcpHttpLayer } from "./mcp.tools.layer.js";
import { ApiSafeTelemetryLive } from "./worker-telemetry.layer.js";
import { ApiWorkerSettingsConfig } from "./worker.config.js";

// The plain/in-process host keeps its modern-only composition. Only the
// native composition supplies the private, stage-bound session namespace.
export const McpSessionHost = Context.Reference<
  Option.Option<{ readonly fetch: HttpEffect }>
>("@taxkit/api/McpSessionHost", { defaultValue: Option.none });

class TaxKitMcpSessions extends DurableObject<
  TaxKitMcpSessions,
  { readonly fetch: HttpEffect<RuntimeContext> }
>()("TaxKitMcpSessions") {}

const SessionRateHeader = "x-taxkit-mcp-calculator-key";

// SDK registration captures these existing services. The SDK reconstructs
// their graph in its native isolate; this is not a second implementation or
// a global work pool. Native protocol parsing/session maps remain native.
export const McpSessionHostLive = Layer.effect(
  McpSessionHost,
  Effect.gen(function* () {
    const analytics = yield* ApiCalculatorDelivery;
    const settings = yield* Effect.cached(ApiWorkerSettingsConfig);
    const telemetry = yield* Layer.build(ApiSafeTelemetryLive);
    const calculator = Layer.succeed(
      PublicCalculatorService,
      yield* PublicCalculatorService
    );
    const content = Layer.succeed(ContentService, yield* ContentService);
    const namespace = yield* TaxKitMcpSessions.pipe(
      Effect.provide(
        TaxKitMcpSessions.make(
          Effect.gen(function* () {
            const state = yield* DurableObjectState;
            return Effect.gen(function* () {
              // A whole native host Scope is the supported expiry boundary. The
              // adapter provides no public per-session removal operation.
              const makeHost = Effect.gen(function* () {
                const config = yield* settings.pipe(Effect.orDie);
                const expires = DateTime.addDuration(
                  yield* DateTime.now,
                  McpSessionLifetime
                );
                const scope = yield* Scope.make();
                return yield* Effect.gen(function* () {
                  const handler = yield* HttpRouter.toHttpEffect(
                    TaxKitMcpHttpLayer(
                      config.publicationOrigin,
                      McpProtocol.v2025_11_25
                    ).pipe(Layer.provide(calculator), Layer.provide(content))
                  ).pipe(
                    Scope.provide(scope),
                    Effect.provideContext(telemetry),
                    Effect.orDie
                  );
                  const initialisations = yield* Ref.make(0);
                  // Only the expiry timestamp is stored by the native alarm API.
                  yield* state.storage.setAlarm(
                    DateTime.toEpochMillis(expires)
                  );
                  return { expires, handler, initialisations, scope } as const;
                }).pipe(
                  Effect.onExit((exit) =>
                    Exit.isFailure(exit)
                      ? Scope.close(scope, exit)
                      : Effect.void
                  )
                );
              }).pipe(
                Effect.updateContext(
                  (context: Context.Context<RuntimeContext>) =>
                    Context.omit(
                      ApiCalculatorEvents,
                      CalculatorRequestRateKey,
                      McpRequestAbortSignal,
                      HttpServerRequest.HttpServerRequest
                    )(context)
                )
              );
              const host = yield* SynchronizedRef.make(
                Option.none<Effect.Success<typeof makeHost>>()
              );
              const requests = yield* Semaphore.make(McpSessionRequestLimit);
              const expire = Effect.gen(function* () {
                const now = yield* DateTime.now;
                return yield* SynchronizedRef.modifyEffect(host, (current) =>
                  Option.match(current, {
                    onNone: () =>
                      Effect.succeed([undefined, Option.none()] as const),
                    onSome: (value) =>
                      DateTime.isGreaterThanOrEqualTo(now, value.expires)
                        ? Scope.close(value.scope, Exit.void).pipe(
                            Effect.as([undefined, Option.none()] as const)
                          )
                        : state.storage
                            .setAlarm(DateTime.toEpochMillis(value.expires))
                            .pipe(Effect.as([undefined, current] as const)),
                  })
                );
              });

              const fetch = Effect.gen(function* () {
                const request = yield* HttpServerRequest.HttpServerRequest;
                const config = yield* settings.pipe(Effect.orDie);
                if (
                  new URL(request.url, config.apiOrigin).pathname !== "/mcp"
                ) {
                  return HttpServerResponse.empty({ status: 404 });
                }
                // Origin refusal precedes admission and native state allocation.
                const origin = Headers.get(request.headers, "origin");
                if (
                  Option.isSome(origin) &&
                  origin.value !== config.publicationOrigin.origin
                ) {
                  return HttpServerResponse.empty({ status: 403 });
                }
                const rawId = Headers.get(request.headers, "mcp-session-id");
                if (
                  Option.isSome(rawId) &&
                  Option.isNone(
                    Schema.decodeUnknownOption(McpSessionId)(rawId.value)
                  )
                ) {
                  return HttpServerResponse.empty({ status: 404 });
                }
                // Native session streams/subscriptions are outside this closed
                // tool contract. POST cancellation notifications still work.
                if (request.method !== "POST") {
                  return HttpServerResponse.empty({ status: 405 });
                }
                const now = yield* DateTime.now;
                const selected = yield* SynchronizedRef.modifyEffect(
                  host,
                  (current) =>
                    Effect.gen(function* () {
                      if (
                        Option.isSome(current) &&
                        DateTime.isGreaterThanOrEqualTo(
                          now,
                          current.value.expires
                        )
                      ) {
                        yield* Scope.close(current.value.scope, Exit.void);
                      }
                      const active = Option.filter(current, (value) =>
                        DateTime.isLessThan(now, value.expires)
                      );
                      if (Option.isSome(active)) {
                        return [active, active] as const;
                      }
                      // An expired/unknown conversation cannot create a host.
                      if (Option.isSome(rawId)) {
                        return [Option.none(), Option.none()] as const;
                      }
                      const created = Option.some(yield* makeHost);
                      return [created, created] as const;
                    })
                );
                if (Option.isNone(selected)) {
                  return HttpServerResponse.empty({ status: 404 });
                }
                const active = selected.value;
                if (Option.isNone(rawId)) {
                  const admitted = yield* Ref.modify(
                    active.initialisations,
                    (count) =>
                      count < McpSessionInitialisationLimit
                        ? ([true, count + 1] as const)
                        : ([false, count] as const)
                  );
                  if (!admitted) {
                    return HttpServerResponse.empty({
                      headers: {
                        "retry-after": String(
                          Math.max(
                            1,
                            Math.ceil(
                              (DateTime.toEpochMillis(active.expires) -
                                DateTime.toEpochMillis(now)) /
                                1000
                            )
                          )
                        ),
                      },
                      status: 429,
                    });
                  }
                }
                const key = Headers.get(
                  request.headers,
                  SessionRateHeader
                ).pipe(
                  Option.flatMap(
                    Schema.decodeUnknownOption(CalculatorClientRateKey)
                  )
                );
                return yield* withCalculatorAnalytics(
                  withBoundedMcpReply(active.handler)
                ).pipe(
                  Effect.provideService(ApiCalculatorDelivery, analytics),
                  Effect.provideService(CalculatorRequestRateKey, key),
                  Effect.provideService(
                    McpRequestAbortSignal,
                    Schema.decodeUnknownOption(Schema.instanceOf(Request))(
                      request.source
                    ).pipe(Option.map((source) => source.signal))
                  )
                );
              }).pipe(
                requests.withPermitsIfAvailable(1),
                Effect.map(
                  Option.getOrElse(() =>
                    HttpServerResponse.empty({ status: 503 })
                  )
                ),
                safeHttpEffect,
                Effect.provideContext(telemetry)
              );
              return {
                alarm: () => expire,
                fetch,
              };
            });
          })
        )
      )
    );
    const fetch = Effect.gen(function* () {
      const request = yield* HttpServerRequest.HttpServerRequest;
      const key = yield* CalculatorRequestRateKey;
      const headers = Headers.remove(request.headers, SessionRateHeader);
      const trusted = Option.isSome(key)
        ? Headers.set(
            headers,
            SessionRateHeader,
            NetAddress.formatIp(Redacted.value(key.value))
          )
        : headers;
      return yield* namespace
        .getByName("legacy-mcp-v2025-11-25")
        .fetch(request.modify({ headers: trusted }));
    });
    return Option.some({ fetch });
  })
);

