        Effect.sync(() => {
          expect(error._tag).toBe("FumadocsSourceLoadError");
          Match.value(error).pipe(
            Match.tags({
              FumadocsPageNotFoundError: (notFoundError) => {
                expect(notFoundError._tag).toBe("FumadocsSourceLoadError");
              },
